\begin{equation}\label{eq:rllp-primal}
\begin{split}
\mathrm{(P):}\quad\min_V& \sum_{s} \rho_0(s)V(s), \\
\st & V(s)\geq  r(s,a)+  \gamma \mathbb{E}_{s'|s,a}[ V(s')] , \forall s, a.
\end{split}
\end{equation}

\begin{equation}\label{eq:rllp-dual}
\begin{split}
\mathrm{(D):}\quad\max_{x\geq0}& \sum_{s,a} r(s,a)w(s,a)x(s,a), \\
\st& \sum_{a}w(s',a)x(s',a)- \sum_{s,a} \gamma P(s'|s,a) w(s,a)x(s,a) = \rho_0(s'), \forall s',
\end{split}
\end{equation}

To simplify the following derivation, we consider an equivalent primal LP formulation with equality constraints by introducing an additional slack variable. Namely, we reformulate \eqref{eq:rllp-primal} as 
\begin{equation}\label{eq:rllp-primal-eq}
\begin{split}
\min_{h\geq0,V}&\  \sum_{s} \rho_0(s)V(s), \\
\st & V(s)=  r(s,a)+  \gamma  \mathbb{E}_{s'|s,a}[ V(s')]+h(s,a), \forall s, a.
\end{split}
\end{equation}

That is to say, $Z$-function is a conditional expectation of $s'$. For the LP problem \eqref{eq:rllp-primal-eq}, the weighted augmented Lagrangian function is defined as 
\begin{equation}\label{randALM}
\mathcal{L}_{\mu}(V,h,x) = \sum_{s} \rho_0(s)V(s) +\frac{1}{2\mu}\sum_{s,a}w(s,a)[Z_\mu(V,h,x,s,a)]^2.
\end{equation}

where $m_V, m_h, m_x$ are integers, $\sigma =  \max(0, x)$ is the ReLU function. The parameters are randomly initialized by either the uniform distribution or normal distribution, i.e.,
\be\label{eq:dist}
\begin{split}
&\phi_{1,i}, \theta_{1,i} \sim \mathcal{U}(\{1,-1\}), \quad \psi_{1,i} = 1, \\
&\phi_{2,i} \sim \mathcal{N}(0, I_{d_{s}}/d_s),\quad \psi_{2,i},\theta_{1,i} \sim \mathcal{N}(0, I_{d_{sa}}/d_{sa}), 
\end{split}
\ee

For simplicity, we assume  that $\|(s,a)\| \leq 1$, which follows that $\|s\| \leq 1$. On $\Xi$, we have
\be\label{eq:bv}
\begin{split}
&|V_\phi(s) - V_{\phi^0}(s)| \leq \frac{1}{\sqrt{m_V}} \sum_{i=1}^{m_V} |\phi_{1,i}| \cdot |\sigma(\phi_{2,i}^Ts) - \sigma((\phi_{2,i}^0)^Ts)| \\
 \leq& \frac{1}{\sqrt{m_V}} \sum_{i=1}^{m_V} |\phi_{1,i}| \cdot |\phi_{2,i}^Ts - (\phi_{2,i}^0)^Ts| \leq \frac{1}{\sqrt{m_V}} \sum_{i=1}^{m_V} \|\phi_{2,i} - (\phi_{2,i}^0)\| \leq R_V^{1/2}.
 \end{split}
\ee

The corresponding norm in $\mathcal{H}$ is denoted by $\|\cdot\|_{\mathcal{H}}$.
Define
\begin{equation}\label{comp-func-non}
 \begin{split}
 \tilde{\mathcal{L}}^k_{\beta,\mu}(V,h,x) 
&:= \sum_{s} \rho_0(s)V(s) +\frac{1}{2\mu}\sum_{s,a}w(s,a)x(s,a)Z_\mu(V,h,x_{\theta^{k}},s,a)\\
&+\frac{\beta}{2}\sum_{s,a} w(s,a)\left[x(s,a) - \left(Z_\mu(V,h,x_{\theta^{k}},s,a)\right)\right]^2.
\end{split}
\end{equation}

\begin{assumption}\label{assum:fc}
    \begin{enumerate}[(i)]
    \item It holds that $\tilde{V}^k \in \mathcal{F}^V_{R_V, m_V}, \tilde{h}^k \in \mathcal{F}^h_{R_h, m_h}, \tilde{x}^k \in \mathcal{F}^x_{R_x, m_x}$ for any $k$.
    \item For any unit vector $u, v$ and nonnegtive scalar $\tau$, $E_w 1_{\{|u^T(s,a)| < \tau\}} \leq c\tau$ and $E_w 1_{\{|v^Ts| < \tau\}} \leq c\tau$ holds, where $c$ is a constant and $E_w f = \sum_{s,a} w(s,a)f(s,a)$.  
\end{enumerate}
\end{assumption}

Assumption \ref{assum:fc} (i) is commonly used in the literature and Assumption \ref{assum:fc} (ii) is on the regularity of the distribution $w$. For convenience, let $\zeta = (\phi, \psi, \theta)$, $\Gamma = (V,h,x)$, $R = \max\{R_V, R_h, R_x\}$ and $m = \min\{m_V, m_h, m_x\}$. The following method is used to minimize \eqref{comp-func}.
Let $\zeta^{k,0} = \zeta^{k}$ and 
\be\label{eq:pjg}
\begin{split}
    \zeta^{k,t+1} &= \Pi_{\zeta \in \Xi}\left(\zeta^{k,t} - \alpha_t \nabla_\zeta \tilde{\mathcal{L}}^k_{\beta,\mu}(V_{\phi^{k,t}},h_{\psi^{k,t}},x_{\theta^{k,t}} )\right), \\
    \zeta^{k+1} &= \frac{1}{T}\sum_{t=1}^T \zeta^{k,t}.
\end{split}
\ee

\begin{lemma}\label{lem:lp}
    If $V^*,h^* = \arg\min_{h \geq 0,V}  \mathcal{L}_{\mu}(V,h, x')$, then the term $Z_\mu(V^*,h^*,x', s,a)$ is an optimal solution of the following problem
\begin{equation}\label{eq:prox-lp}
\begin{split}
\max_x& \sum_{s,a} r(s,a)w(s,a)x(s,a) - \frac{1}{2\mu}\sum_{s,a} w(s,a)(x(s,a) - x'(s,a))^2  \\
\st&  \sum_{s,a} (\delta_{s'}(s) - \gamma P(s'|s,a)) w(s,a)x(s,a) = \rho_0(s'), \forall s' \\
&x(s,a) \geq 0, \forall s,a.
\end{split}
\end{equation}
The optimal value of problem \eqref{eq:prox-lp} is equal to 
\be\label{eq:Fmu}
\mathcal{F}_{\mu}(V^*,h^*,x') := \mathcal{L}_{\mu}(V^*,h^*, x') - \frac{1}{2\mu}\sum_{s,a} w(s,a)x'(s,a)^2.
\ee

\end{lemma}

\begin{proof}
The KKT condition of the problem \eqref{eq:prox-lp} can be written as  
\bea
\begin{split}
&x(s,a) = x'(s,a) + \mu \left(h(s,a) + r(s,a)+\sum_{s'} \gamma P(s'|s,a) V(s') - V(s)\right), \forall s,a,\\
&\sum_{s,a} (\delta_{s'}(s) - \gamma P(s'|s,a)) w(s,a)x(s,a) = \rho_0(s'), \forall s', \label{eq:kkt} \\
&x(s,a) \geq 0, h(s,a) \geq 0, \forall s,a,
\end{split}
\eea
where $V$ and $h$ are the dual variables. Then, $x^*$ is an optimal solution if and only if there exists variables $V$ and $h$ such that $x^*, V$ and $h$ satisfy the condition \eqref{eq:kkt}. Suppose that $V^*,h^* = \arg\min_{h\geq 0,V}  \mathcal{L}_{\mu}(V,h, x')$. We have the optimality condition
\be\label{eq:kkt-lg}
    \begin{split}
    &\rho_0(s') - \sum_{s,a}w(s,a)Z_\mu(V^*,h^*,x',s,a)(\delta_{s'}(s) - \gamma P(s'|s,a)) = 0, \forall s' \\
    & \mu h(x,a) = \left[- x'(s,a) - \mu\left(r(s,a)+\sum_{s'} \gamma P(s'|s,a) V(s') - V(s)\right)\right]_+.
\end{split}
\ee
Let 
\bee
    \begin{split}
    x(s,a) &= Z_\mu(V^*,h^*,x', s,a)\\ 
    &= \left[x'(s,a) + \mu \left(r(s,a)+\sum_{s'} \gamma P(s'|s,a) V(s') - V(s)\right)\right]_+ \geq 0.
    \end{split}
\eee
Then the KKT condition \eqref{eq:kkt} holds, i.e., $x(s,a) = Z_\mu(V^*,h^*,x',s,a)$ is an optimal solution of \eqref{eq:prox-lp}.

Let $x^* = Z_\mu(V^*,h^*,x',s,a)$, then we obtain
\bee
\begin{split}
&\mathcal{F}_{\mu}(V^*,h^*,x') \\
= & \sum_s \rho_0(s) V(s) + \frac{1}{2\mu}\sum_{s,a}w(s,a) x^*(s,a)^2 - \frac{1}{2\mu}\sum_{s,a} w(s,a)x'(s,a)^2 \\
 = & \sum_s \rho_0(s) V(s) + \frac{1}{\mu}\sum_{s,a}w(s,a) x^*(s,a)(x^*(s,a)-x'(s,a)) \\
& - \frac{1}{2\mu}\sum_{s,a} w(s,a)(x^*(s,a)-x'(s,a))^2 \\
= & \sum_{s,a} r(s,a)w(s,a)x^*(s,a) - \frac{1}{2\mu}\sum_{s,a} w(s,a)(x^*(s,a)-x'(s,a))^2, 
\end{split}
\eee
where the last inequality is due to the first equation in \eqref{eq:kkt-lg} and the definition of $Z_\mu(V^*,h^*,x',s,a)$, which completes the proof.
\end{proof}

\begin{proof}
    The function $\tilde{\mathcal{L}}^k_{\beta,\mu}(V,h,x)$ is a quadratic function. Hence, the gradient of $\tilde{\mathcal{L}}^k_{\beta,\mu}(V,h,x)$ is $L$-Lipschitz continuous. To show the convexity of $\tilde{\mathcal{L}}^k_{\beta,\mu}(V,h,x)$, we only need to show that the quadratic part is nonnegtive.  If $\beta > \frac{1}{4\mu}$, by rearranging the quadratic term in $\tilde{\mathcal{L}}^k_{\beta,\mu}(V,h,x)$, we obtain
    \bee
 \begin{split}
& \frac{1}{2\mu}\sum_{s,a}w(s,a)x(s,a)Z_\mu(V,h,x_{\theta^{k}},s,a)
+\frac{\beta}{2}\sum_{s,a} w(s,a)\left[x(s,a) - \left(Z_\mu(V,h,x_{\theta^{k}},s,a)\right)\right]^2 \\
=& \frac{\beta}{2}\sum_{s,a}w(s,a) \left\{ \left[(1-\frac{1}{2\mu \beta})x(s,a) -  Z_\mu(V,h,x_{\theta^{k}},s,a) \right]^2 + \frac{1}{4\mu\beta}(1-\frac{1}{4\mu\beta})x(s,a)^2 \right\} \\
\geq & \frac{1}{2\mu}(1-\frac{1}{4\mu\beta})\sum_{s,a}w(s,a)x(s,a)^2 \geq 0.
\end{split}
\eee
Hence, $\tilde{\mathcal{L}}^k_{\beta,\mu}(V,h,x)$ is restricted strongly convex and $c$ is the smallest positive eigenvalue of the Hessian of $\tilde{\mathcal{L}}^k_{\beta,\mu}(V,h,x)$. It also implies that $\tilde{\mathcal{L}}^k_{\beta,\mu}(V,h,x)$ is $\frac{1}{2\mu}(1-\frac{1}{4\mu\beta})$-strongly convex with respect to $x$.
\end{proof}

\begin{lemma}\label{lem:conv1}
    Suppose that Assumption \ref{assum:fc} holds and $\beta > \frac{1}{4\mu}$. Let  $\zeta^{k,t} = (\phi^{k,t}, \psi^{k,t}, \theta^{k,t})$ be a sequence generated by the projected gradient descent method \eqref{eq:pjg} with $\alpha_t = \alpha \leq \frac{1}{\sqrt{3}L}$.
    Then we have
    \be\label{eq:conv1}
    \begin{split}
   & E_0\left(\tilde{\mathcal{L}}^k_{\beta,\mu}(V_{\phi^{k+1}},h_{\psi^{k+1}},x_{\theta^{k+1}}) - \tilde{\mathcal{L}}^k_{\beta,\mu}(\tilde{V}^{k+1}, \tilde{h}^{k+1}, \tilde{x}^{k+1})\right) \\
    = &O\left(R^2T^{-1} + R^{5/2}m^{-1/4} + R^{3}m^{-1/2}\right).
    \end{split}
    \ee
    Furthermore, it holds that
    \be\label{eq:conv2}
    E_{0,w}(x_{\theta^{k+1}}(s,a) - \tilde{x}^{k+1}(s,a))^2 = O\left(R^2T^{-1} + R^{5/2}m^{-1/4} + R^{3}m^{-1/2}\right). 
    \ee
%    \beaa
%        E_w(x_{\theta^{k,T}}(s,a) - x_{\theta^*}^0(s,a))^2 &=& O(R^3m^{-1/2}+R^2/T), \\
%        E_w(Z_\mu(V_{\phi^{k,T}},h_{\psi^{k,T}},x_{\theta^k},s,a) - Z_\mu(V_{\phi^*},h_{\psi^*},x_{\theta^k},s,a))^2 &=& O(R^3m^{-1/2}+R^2/T).
%    \eeaa
\end{lemma}

