\be\label{eq:cvx1}
\begin{split}
&\tilde{\mathcal{L}}^k_{\beta,\mu}(V_{\phi^{k,t+1}}^0,h_{\psi^{k,t+1}}^0,x_{\theta^{k,t+1}}^0) - \tilde{\mathcal{L}}^k_{\beta,\mu}(V_{\phi^{k,t}}^0,h_{\psi^{k,t}}^0,x_{\theta^{k,t}}^0) \\
\leq & \nabla_\zeta \tilde{\mathcal{L}}^k_{\beta,\mu}(V_{\phi^{k,t}}^0,h_{\psi^{k,t}}^0,x_{\theta^{k,t}}^0)^T(\zeta^{k,t+1} - \zeta^{k,t} ) + \frac{\sqrt{3}L}{2}\|\zeta^{k,t+1} - \zeta^{k,t} \|_2^2.
